/* Token Radar's page: dark ink, amber signal, one readable table. No network: every font is the system stack. */
:root {
  --ink: #0e1218;
  --panel: #161c26;
  --panel-2: #1c2431;
  --line: #2a3444;
  --text: #e8edf3;
  --muted: #9aa7b8;
  --amber: #f5b942;
  --amber-soft: #f5b94222;
  --green: #4cc38a;
  --red: #e5534b;
  --blue: #6cb4ff;
  --radius: 10px;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--ink);
  color: var(--text);
  font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.wrap { max-width: 1180px; margin: 0 auto; padding: 0 20px; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* Header */
.top { background: linear-gradient(180deg, #1a2230, var(--ink)); border-bottom: 1px solid var(--line); padding: 22px 0 16px; }
.brand { display: flex; gap: 14px; align-items: flex-start; }
.mark { font-size: 34px; line-height: 1; color: var(--amber); }
h1 { margin: 0; font-size: 30px; letter-spacing: -0.02em; }
.tag { margin: 2px 0 0; color: var(--muted); max-width: 640px; }
.stats { display: flex; flex-wrap: wrap; gap: 8px 28px; margin: 16px 0 0; padding: 0; }
.stats div { display: flex; gap: 6px; align-items: baseline; }
.stats dt { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.stats dd { margin: 0; font-weight: 700; font-size: 17px; }

/* Tabs */
.tabs { display: flex; gap: 4px; margin: 18px 0 14px; border-bottom: 1px solid var(--line); }
.tab {
  appearance: none; border: 0; background: none; color: var(--muted);
  font: inherit; font-weight: 600; padding: 9px 14px; cursor: pointer;
  border-bottom: 2px solid transparent; margin-bottom: -1px;
}
.tab:hover { color: var(--text); }
.tab.is-active { color: var(--amber); border-bottom-color: var(--amber); }

/* Toolbar */
.toolbar { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-bottom: 8px; }
.field.grow { flex: 1 1 220px; }
input[type="search"], select {
  width: 100%; background: var(--panel); color: var(--text);
  border: 1px solid var(--line); border-radius: 8px; padding: 9px 11px; font: inherit;
}
input[type="search"]:focus, select:focus { outline: 2px solid var(--amber); outline-offset: 1px; }
.check { display: flex; gap: 7px; align-items: center; color: var(--muted); cursor: pointer; white-space: nowrap; }
.check input { accent-color: var(--amber); width: 16px; height: 16px; }
.count { color: var(--muted); margin: 4px 0 10px; font-size: 13px; }
.lede { color: var(--muted); margin: 0 0 14px; max-width: 760px; }

/* Tables */
.tablewrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
thead th {
  text-align: left; color: var(--muted); font-size: 12px; text-transform: uppercase;
  letter-spacing: 0.05em; padding: 11px 12px; border-bottom: 1px solid var(--line);
  background: var(--panel-2); position: sticky; top: 0;
}
tbody td { padding: 9px 12px; border-bottom: 1px solid var(--line); vertical-align: middle; }
tbody tr:last-child td { border-bottom: 0; }
tbody tr { cursor: pointer; }
tbody tr:hover td { background: #1e2837; }
tbody tr.is-selected td { background: var(--amber-soft); }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.proto { font-weight: 700; }
.slug { display: block; font-weight: 400; color: var(--muted); font-size: 12px; }
.badge {
  display: inline-block; margin-left: 7px; padding: 1px 7px; border-radius: 20px;
  background: var(--amber-soft); color: var(--amber); font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.04em; vertical-align: 1px;
}
.up { color: var(--green); }
.down { color: var(--red); }
.meter { display: inline-block; width: 64px; height: 7px; background: #2a3444; border-radius: 4px; vertical-align: middle; margin-right: 7px; overflow: hidden; }
.meter i { display: block; height: 100%; background: var(--amber); border-radius: 4px; }
.hint { color: var(--muted); font-size: 13px; }

/* Method view */
.method { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px 18px; }
.card h2 { margin: 0 0 8px; font-size: 17px; }
.card h3 { margin: 14px 0 6px; font-size: 14px; color: var(--amber); }
.card p, .card li { color: #c6d0dc; }
.card p { margin: 6px 0; }
.formula {
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  font-size: 13px; background: var(--ink); border: 1px solid var(--line);
  border-radius: 8px; padding: 12px 14px; overflow-x: auto; white-space: pre-wrap; color: var(--text);
}
.comps { width: 100%; }
.comps td, .comps th { padding: 5px 8px; border-bottom: 1px solid var(--line); font-size: 13px; }
.comps th { background: none; position: static; }

/* Detail drawer */
.drawer {
  position: fixed; top: 0; right: 0; bottom: 0; width: min(460px, 100vw);
  background: var(--panel); border-left: 1px solid var(--line); z-index: 20;
  overflow-y: auto; padding: 22px 22px 40px; box-shadow: -18px 0 44px rgba(0, 0, 0, 0.45);
}
.drawer-close {
  position: sticky; top: 0; float: right; appearance: none; border: 1px solid var(--line);
  background: var(--panel-2); color: var(--text); border-radius: 8px; width: 34px; height: 34px;
  font-size: 15px; cursor: pointer;
}
.detail h2 { margin: 0 0 2px; font-size: 22px; }
.detail .sub { color: var(--muted); margin: 0 0 14px; }
.facts { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 16px; margin: 0 0 16px; }
.facts div { background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; }
.facts dt { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; }
.facts dd { margin: 2px 0 0; font-weight: 700; font-variant-numeric: tabular-nums; }
.breakdown { margin: 0 0 16px; }
.breakdown .rowline { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid var(--line); font-size: 14px; }
.breakdown .rowline span:first-child { color: var(--muted); }
.breakdown .rowline.total { font-weight: 800; border-bottom: 0; }
.breakdown .rowline.total span:last-child { color: var(--amber); }
.steps { list-style: none; margin: 0; padding: 0; counter-reset: step; }
.steps li {
  counter-increment: step; position: relative; padding: 10px 0 10px 38px;
  border-bottom: 1px solid var(--line); font-size: 14px;
}
.steps li:last-child { border-bottom: 0; }
.steps li::before {
  content: counter(step); position: absolute; left: 0; top: 10px; width: 26px; height: 26px;
  border-radius: 50%; background: var(--amber-soft); color: var(--amber);
  font-weight: 800; font-size: 13px; display: flex; align-items: center; justify-content: center;
}
.detail h3 { margin: 18px 0 6px; font-size: 15px; color: var(--amber); }

.foot { color: var(--muted); font-size: 13px; padding: 26px 20px 40px; }
.foot p { margin: 0; }
.view[hidden], .drawer[hidden] { display: none; }
@media (max-width: 640px) {
  h1 { font-size: 24px; }
  .facts { grid-template-columns: 1fr; }
  thead th:nth-child(4), tbody td:nth-child(4) { display: none; }
}
